extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var audio = await instantiate_script("res://assets/audio/audio.gd")
	if not check("instantiate", audio != null, "Lo script res://assets/audio/audio.gd deve potersi istanziare"):
		return

	if not check("play_voice_func", has_function(audio, "play_voice"), "AudioManager deve avere il metodo play_voice"):
		return
	if not check("stop_voice_func", has_function(audio, "stop_voice"), "AudioManager deve avere il metodo stop_voice"):
		return
	if not check("get_voice_func", has_function(audio, "get_voice_player"), "AudioManager deve avere il metodo get_voice_player"):
		return

	var voice_player = call_if_exists(audio, "get_voice_player")
	if not check("voice_player_exists", voice_player is AudioStreamPlayer, "get_voice_player() deve restituire un nodo AudioStreamPlayer"):
		return

	var voice_1 := AudioStreamWAV.new()
	voice_1.format = AudioStreamWAV.FORMAT_8_BIT
	voice_1.data = PackedByteArray([128, 128, 128, 128])

	var voice_2 := AudioStreamWAV.new()
	voice_2.format = AudioStreamWAV.FORMAT_8_BIT
	voice_2.data = PackedByteArray([128, 128, 128, 128])

	call_if_exists(audio, "play_voice", [voice_1])
	var playing_1: bool = bool(get_prop(voice_player, "playing", false))
	var stream_1 = get_prop(voice_player, "stream")
	check("voice_1_playing", playing_1 and stream_1 == voice_1, "play_voice() deve avviare la riproduzione del file vocale")

	call_if_exists(audio, "play_voice", [voice_2])
	var playing_2: bool = bool(get_prop(voice_player, "playing", false))
	var stream_2 = get_prop(voice_player, "stream")
	check("voice_2_replaces", playing_2 and stream_2 == voice_2, "Una nuova voce deve sostituire immediatamente quella precedente sullo stesso canale")

	call_if_exists(audio, "stop_voice")
	var playing_after: bool = bool(get_prop(voice_player, "playing", false))
	check("voice_stopped", not playing_after, "stop_voice() deve fermare la riproduzione della voce")
